    /** The app's events from log index [from], then live, until the collector stops. */
    fun events(from: Long = 0): Flow<EventFrame> {
        val node = client ?: throw UnsupportedOperationException("events needs a CalimeroClient")
        return node.events(app, from).map { EventFrame(it.id, Event.decode(it.kind, it.data)) }
    }

    private suspend fun <T> invokeCall(
        method: String,
        args: JsonObject,
        idempotencyKey: String?,
        result: KSerializer<T>,
    ): T {
        val answer =
            if (client == null) {
                if (idempotencyKey != null) throw UnsupportedOperationException("$method: a contract makes its own idempotency key")
                json.parseToJsonElement(contract.execute(method, args.toString()))
            } else {
                client.apps.method(app, method, args, idempotencyKey = idempotencyKey ?: newKey()).result ?: JsonNull
            }
        return json.decodeFromJsonElement(result, answer)
    }

    private suspend fun <T> invokeView(
        method: String,
        args: JsonObject,
        stale: Boolean,
        minIndex: Long,
        result: KSerializer<T>,
    ): T {
        val answer =
            if (client == null) {
                json.parseToJsonElement(contract.query(method, args.toString()))
            } else {
                val consistency = if (stale) AppMethodRequest.Consistency.STALE else AppMethodRequest.Consistency.STRONG
                client.apps.method(app, method, args, consistency = consistency, minIndex = minIndex).result ?: JsonNull
            }
        return json.decodeFromJsonElement(result, answer)
    }

    private suspend fun <T> invokeConfirmed(
        method: String,
        args: JsonObject,
        passkey: PasskeyProvider,
        idempotencyKey: String?,
        result: KSerializer<T>,
    ): T {
        val node = client ?: throw UnsupportedOperationException("$method needs a passkey step-up, so a CalimeroClient")
        val answer = node.apps.method(app, method, args, idempotencyKey = idempotencyKey ?: newKey(), passkey = passkey).result ?: JsonNull
        return json.decodeFromJsonElement(result, answer)
    }

    /** An event of the app, as [events] and `MeroAppBackend.events` carry it. */
    sealed interface Event {
        /** The event `AlertTriggered`. */
        data class AlertTriggered(
            val message: String,
            val recipients: List<String>,
            val ruleId: String,
            val sheetId: String,
        ) : Event

        /** The event `AttachmentsChanged`. */
        data class AttachmentsChanged(
            val sheetId: String,
        ) : Event

        /** The event `AxesChanged`. */
        data class AxesChanged(
            val count: UInt,
            val sheetId: String,
        ) : Event

        /** The event `CellCleared`. */
        data class CellCleared(
            val colId: String,
            val rowId: String,
            val sheetId: String,
        ) : Event

        /** The event `CellUpdated`. */
        data class CellUpdated(
            val id: String,
            val sheetId: String,
        ) : Event

        /** The event `CellsChanged`. */
        data class CellsChanged(
            val count: UInt,
            val sheetId: String,
        ) : Event

        /** The event `ChartsChanged`. */
        data class ChartsChanged(
            val sheetId: String,
        ) : Event

        /** The event `CommentAdded`. */
        data class CommentAdded(
            val author: String,
            val id: String,
            val mentions: List<String>,
            val sheetId: String,
        ) : Event

        /** The event `CommentChanged`. */
        data class CommentChanged(
            val id: String,
            val sheetId: String,
        ) : Event

        /** The event `LinkedChanged`. */
        data class LinkedChanged(
            val sheetId: String,
        ) : Event

        /** The event `MemberJoined`. */
        data class MemberJoined(
            val id: String,
            val nickname: String,
        ) : Event

        /** The event `MemberRenamed`. */
        data class MemberRenamed(
            val id: String,
            val nickname: String,
        ) : Event

        /** The event `NamedRangesChanged`. */
        data class NamedRangesChanged(
            val name: String,
        ) : Event

        /** The event `NoteChanged`. */
        data class NoteChanged(
            val colId: String,
            val rowId: String,
            val sheetId: String,
        ) : Event

        /** The event `ProjectInitialized`. */
        data class ProjectInitialized(
            val id: String,
            val name: String,
        ) : Event

        /** The event `ProtectionsChanged`. */
        data class ProtectionsChanged(
            val sheetId: String,
        ) : Event

        /** The event `PublicationsChanged`. */
        data class PublicationsChanged(
            val sheetId: String,
        ) : Event

        /** The event `RolesChanged`. */
        data class RolesChanged(
            val memberId: String,
        ) : Event

        /** The event `RulesChanged`. */
        data class RulesChanged(
            val sheetId: String,
        ) : Event

        /** The event `SheetCreated`. */
        data class SheetCreated(
            val id: String,
            val name: String,
        ) : Event

        /** The event `SheetDeleted`. */
        data class SheetDeleted(
            val id: String,
        ) : Event

        /** The event `SheetRenamed`. */
        data class SheetRenamed(
            val id: String,
            val name: String,
        ) : Event

        /** The event `SheetViewChanged`. */
        data class SheetViewChanged(
            val sheetId: String,
        ) : Event

        /** The event `StylesChanged`. */
        data class StylesChanged(
            val sheetId: String,
        ) : Event

        /** An event this client does not know: one a newer release of the app added. */
        data class Unknown(
            val kind: String,
            val data: JsonElement,
        ) : Event

        companion object {
            /** An event's [kind] and [data], typed; a known kind whose data does not fit throws [SerializationException]. */
            fun decode(
                kind: String,
                data: JsonElement,
            ): Event =
                when (kind) {
                    "AlertTriggered" -> AlertTriggered(message = field(data, "message", String.serializer()), recipients = field(data, "recipients", ListSerializer(String.serializer())), ruleId = field(data, "ruleId", String.serializer()), sheetId = field(data, "sheetId", String.serializer()))
                    "AttachmentsChanged" -> AttachmentsChanged(sheetId = field(data, "sheetId", String.serializer()))
                    "AxesChanged" -> AxesChanged(count = field(data, "count", UInt.serializer()), sheetId = field(data, "sheetId", String.serializer()))
                    "CellCleared" -> CellCleared(colId = field(data, "colId", String.serializer()), rowId = field(data, "rowId", String.serializer()), sheetId = field(data, "sheetId", String.serializer()))
                    "CellUpdated" -> CellUpdated(id = field(data, "id", String.serializer()), sheetId = field(data, "sheetId", String.serializer()))
                    "CellsChanged" -> CellsChanged(count = field(data, "count", UInt.serializer()), sheetId = field(data, "sheetId", String.serializer()))
                    "ChartsChanged" -> ChartsChanged(sheetId = field(data, "sheetId", String.serializer()))
                    "CommentAdded" -> CommentAdded(author = field(data, "author", String.serializer()), id = field(data, "id", String.serializer()), mentions = field(data, "mentions", ListSerializer(String.serializer())), sheetId = field(data, "sheetId", String.serializer()))
                    "CommentChanged" -> CommentChanged(id = field(data, "id", String.serializer()), sheetId = field(data, "sheetId", String.serializer()))
                    "LinkedChanged" -> LinkedChanged(sheetId = field(data, "sheetId", String.serializer()))
                    "MemberJoined" -> MemberJoined(id = field(data, "id", String.serializer()), nickname = field(data, "nickname", String.serializer()))
                    "MemberRenamed" -> MemberRenamed(id = field(data, "id", String.serializer()), nickname = field(data, "nickname", String.serializer()))
                    "NamedRangesChanged" -> NamedRangesChanged(name = field(data, "name", String.serializer()))
                    "NoteChanged" -> NoteChanged(colId = field(data, "colId", String.serializer()), rowId = field(data, "rowId", String.serializer()), sheetId = field(data, "sheetId", String.serializer()))
                    "ProjectInitialized" -> ProjectInitialized(id = field(data, "id", String.serializer()), name = field(data, "name", String.serializer()))
                    "ProtectionsChanged" -> ProtectionsChanged(sheetId = field(data, "sheetId", String.serializer()))
                    "PublicationsChanged" -> PublicationsChanged(sheetId = field(data, "sheetId", String.serializer()))
                    "RolesChanged" -> RolesChanged(memberId = field(data, "memberId", String.serializer()))
                    "RulesChanged" -> RulesChanged(sheetId = field(data, "sheetId", String.serializer()))
                    "SheetCreated" -> SheetCreated(id = field(data, "id", String.serializer()), name = field(data, "name", String.serializer()))
                    "SheetDeleted" -> SheetDeleted(id = field(data, "id", String.serializer()))
                    "SheetRenamed" -> SheetRenamed(id = field(data, "id", String.serializer()), name = field(data, "name", String.serializer()))
                    "SheetViewChanged" -> SheetViewChanged(sheetId = field(data, "sheetId", String.serializer()))
                    "StylesChanged" -> StylesChanged(sheetId = field(data, "sheetId", String.serializer()))
                    else -> Unknown(kind, data)
                }
        }
    }

    /** One frame of [events]: the event's log position (`index:seq`) and the event. */
    data class EventFrame(
        val id: String,
        val event: Event,
    )

    /** The app's refusal: a `422 APP_ERROR`'s code and fields ([AppError.appCode], [AppError.fields]), typed. */
    sealed interface Refusal {
        /** The error `Forbidden`. */
        data class Forbidden(
            val message: String,
        ) : Refusal

        /** The error `Invalid`. */
        data class Invalid(
            val message: String,
        ) : Refusal

        /** The error `NotFound`. */
        data class NotFound(
            val message: String,
        ) : Refusal

        /** A code this client does not know, or fields that do not fit it. */
        data class Unknown(
            val code: String,
            val fields: JsonObject,
        ) : Refusal

        companion object {
            /** [error]'s code and fields, typed. */
            fun from(error: AppError): Refusal =
                try {
                    when (error.appCode) {
                        "Forbidden" -> Forbidden(message = field(error.fields, "message", String.serializer()))
                        "Invalid" -> Invalid(message = field(error.fields, "message", String.serializer()))
                        "NotFound" -> NotFound(message = field(error.fields, "message", String.serializer()))
                        else -> Unknown(error.appCode, error.fields)
                    }
                } catch (e: IllegalArgumentException) {
                    Unknown(error.appCode, error.fields)
                }
        }
    }

    /** A `u64` as the wire carries it: a decimal string (a number is read too). */
    object U64AsString : KSerializer<ULong> {
        override val descriptor: SerialDescriptor = PrimitiveSerialDescriptor("calimero.u64", PrimitiveKind.STRING)

        override fun serialize(
            encoder: Encoder,
            value: ULong,
        ) = encoder.encodeString(value.toString())

        override fun deserialize(decoder: Decoder): ULong {
            val text = (decoder as? JsonDecoder)?.decodeJsonElement()?.jsonPrimitive?.content ?: decoder.decodeString()
            return text.toULongOrNull() ?: throw SerializationException("not a u64: $text")
        }
    }

    /** An `i64` as the wire carries it: a decimal string (a number is read too). */
    object I64AsString : KSerializer<Long> {
        override val descriptor: SerialDescriptor = PrimitiveSerialDescriptor("calimero.i64", PrimitiveKind.STRING)

        override fun serialize(
            encoder: Encoder,
            value: Long,
        ) = encoder.encodeString(value.toString())

        override fun deserialize(decoder: Decoder): Long {
            val text = (decoder as? JsonDecoder)?.decodeJsonElement()?.jsonPrimitive?.content ?: decoder.decodeString()
            return text.toLongOrNull() ?: throw SerializationException("not an i64: $text")
        }
    }

    /** `bytes` as the wire carries them: base64url without padding (padding is read too). */
    @OptIn(ExperimentalEncodingApi::class)
    object Base64Url : KSerializer<ByteArray> {
        override val descriptor: SerialDescriptor = PrimitiveSerialDescriptor("calimero.bytes", PrimitiveKind.STRING)

        override fun serialize(
            encoder: Encoder,
            value: ByteArray,
        ) = encoder.encodeString(Base64.UrlSafe.encode(value).trimEnd('='))

        override fun deserialize(decoder: Decoder): ByteArray {
            val text = decoder.decodeString().trimEnd('=')
            return try {
                Base64.UrlSafe.decode(text.padEnd((text.length + 3) / 4 * 4, '='))
            } catch (e: IllegalArgumentException) {
                throw SerializationException("not base64url: ${e.message}")
            }
        }
    }

    companion object {
        private val json = Json { ignoreUnknownKeys = true }

        private fun newKey(): String = java.util.UUID.randomUUID().toString()

        private fun <T> encode(
            serializer: KSerializer<T>,
            value: T,
        ): JsonElement = json.encodeToJsonElement(serializer, value)

        /** Field [name] of an event's or error's [data]; a missing one reads as `null`. */
        private fun <T> field(
            data: JsonElement,
            name: String,
            serializer: KSerializer<T>,
        ): T = json.decodeFromJsonElement(serializer, (data as? JsonObject)?.get(name) ?: JsonNull)
    }
}
